import React, { useEffect, useState, useContext } from "react";
import { AuthContext } from "../Context/AuthContext";
import { useNavigate } from "react-router-dom";
import {
  Users,
  BookOpen,
  Calendar,
  CheckCircle,
  XCircle,
  Clock,
  School,
  ShieldCheck,
} from "lucide-react";
import api from "../api/axios";
import Loading from "../Components/Loading";

const Admin = () => {
  const { user, isAuth } = useContext(AuthContext);
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState("ENROLLMENTS"); // "ENROLLMENTS" | "BATCHES" | "CLASSES"
  const [enrollments, setEnrollments] = useState([]);
  const [batches, setBatches] = useState([]);
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedBatchForApproval, setSelectedBatchForApproval] = useState({});
  const [actionMessage, setActionMessage] = useState("");

  const fetchData = async () => {
    setLoading(true);
    try {
      const [enrollRes, batchRes, classRes] = await Promise.all([
        api.get("/enrollments"),
        api.get("/batches"),
        api.get("/public/classes"),
      ]);

      if (enrollRes.data.success) setEnrollments(enrollRes.data.data);
      if (batchRes.data.success) setBatches(batchRes.data.data);
      if (classRes.data.success) {
        // Unique classes
        const seen = new Set();
        const unique = [];
        classRes.data.data.forEach((c) => {
          if (!seen.has(c.class_number)) {
            seen.add(c.class_number);
            unique.push(c);
          }
        });
        unique.sort((a, b) => a.class_number - b.class_number);
        setClasses(unique);
      }
    } catch (err) {
      console.error("Failed to fetch admin data:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!isAuth && !localStorage.getItem("sm_token")) {
      navigate("/login");
      return;
    }
    fetchData();
  }, [isAuth, navigate]);

  const handleApprove = async (enrollmentId, studentClass) => {
    const batchId = selectedBatchForApproval[enrollmentId] || batches.find((b) => b.class_number === studentClass)?._id;

    try {
      const res = await api.patch(`/enrollments/${enrollmentId}/approve`, {
        batch_id: batchId,
      });
      if (res.data.success) {
        setActionMessage(res.data.message);
        setTimeout(() => setActionMessage(""), 5000);
        fetchData(); // Refresh list
      }
    } catch (err) {
      alert(err.response?.data?.message || "Failed to approve enrollment");
    }
  };

  const handleReject = async (enrollmentId) => {
    if (!window.confirm("Are you sure you want to reject this inquiry?")) return;

    try {
      const res = await api.patch(`/enrollments/${enrollmentId}/reject`, {
        rejection_reason: "Batch full for this term",
      });
      if (res.data.success) {
        fetchData();
      }
    } catch (err) {
      alert("Failed to reject");
    }
  };

  if (loading) return <Loading />;

  const pendingEnrollments = enrollments.filter((e) => e.status === "PENDING");
  const approvedEnrollments = enrollments.filter((e) => e.status === "APPROVED");

  return (
    <div className="min-h-screen bg-slate-50 py-8 px-4 md:px-8 lg:px-12">
      <div className="max-w-7xl mx-auto space-y-8">
        {/* Top Bar / Header */}
        <div className="bg-[#304b62] text-white rounded-3xl p-6 md:p-8 shadow-lg flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-[#d49539] text-xs font-bold uppercase tracking-wider mb-1">
              <ShieldCheck size={16} /> Institute Command Center
            </div>
            <h1 className="text-2xl md:text-4xl font-black">
              Welcome, {user?.name || "Coaching Administrator"}
            </h1>
            <p className="text-slate-300 text-xs md:text-sm mt-1">
              Apex Academy • Management Portal for Classes 1 to 10
            </p>
          </div>

          <div className="flex items-center gap-2 bg-white/10 px-4 py-2 rounded-xl text-xs font-semibold border border-white/20">
            <School size={16} className="text-[#d49539]" /> 10 Classes Offered • {batches.length} Active Batches
          </div>
        </div>

        {/* Action Feedback Banner */}
        {actionMessage && (
          <div className="p-4 bg-emerald-50 border border-emerald-300 text-emerald-800 rounded-2xl flex items-center gap-3 text-sm font-semibold animate-fadeIn shadow-sm">
            <CheckCircle size={20} className="text-emerald-600 shrink-0" />
            {actionMessage}
          </div>
        )}

        {/* KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-2">
            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between">
              Pending Inquiries <Clock size={16} className="text-[#d49539]" />
            </div>
            <div className="text-3xl font-black text-[#304b62]">{pendingEnrollments.length}</div>
            <div className="text-xs text-slate-500 font-medium">Awaiting admission approval</div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-2">
            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between">
              Active Batches <Calendar size={16} className="text-[#304b62]" />
            </div>
            <div className="text-3xl font-black text-[#304b62]">{batches.length}</div>
            <div className="text-xs text-slate-500 font-medium">Across Classes 1 to 10</div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-2">
            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between">
              Enrolled Students <Users size={16} className="text-emerald-500" />
            </div>
            <div className="text-3xl font-black text-emerald-600">
              {batches.reduce((acc, b) => acc + (b.student_ids?.length || 0), 0) + approvedEnrollments.length}
            </div>
            <div className="text-xs text-slate-500 font-medium">Active enrolled students</div>
          </div>

          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-2">
            <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between">
              CBSE Classes <BookOpen size={16} className="text-purple-500" />
            </div>
            <div className="text-3xl font-black text-[#304b62]">{classes.length || 10}</div>
            <div className="text-xs text-slate-500 font-medium">Classes 1 through 10</div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex items-center gap-3 border-b border-slate-200 pb-3">
          <button
            onClick={() => setActiveTab("ENROLLMENTS")}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === "ENROLLMENTS"
                ? "bg-[#304b62] text-white shadow-md"
                : "bg-white text-slate-600 hover:bg-slate-100 border border-slate-200"
            }`}
          >
            Admission Inquiries
            {pendingEnrollments.length > 0 && (
              <span className="bg-[#d49539] text-white text-xs px-2 py-0.5 rounded-full">
                {pendingEnrollments.length}
              </span>
            )}
          </button>

          <button
            onClick={() => setActiveTab("BATCHES")}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === "BATCHES"
                ? "bg-[#304b62] text-white shadow-md"
                : "bg-white text-slate-600 hover:bg-slate-100 border border-slate-200"
            }`}
          >
            Batches & Timetable
          </button>

          <button
            onClick={() => setActiveTab("CLASSES")}
            className={`px-5 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 ${
              activeTab === "CLASSES"
                ? "bg-[#304b62] text-white shadow-md"
                : "bg-white text-slate-600 hover:bg-slate-100 border border-slate-200"
            }`}
          >
            Class Catalog (1–10)
          </button>
        </div>

        {/* Tab 1: Admission Inquiries Pipeline */}
        {activeTab === "ENROLLMENTS" && (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-extrabold text-[#304b62]">Inbound Admission Inquiries</h3>
                <p className="text-xs text-slate-500">
                  Review public inquiries, approve students, and automatically assign them to batches.
                </p>
              </div>
            </div>

            {enrollments.length === 0 ? (
              <div className="p-12 text-center text-slate-400">
                <p>No admission inquiries submitted yet.</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-50 text-xs font-bold uppercase text-slate-500 tracking-wider border-b border-slate-200">
                    <tr>
                      <th className="p-4 pl-6">Student Details</th>
                      <th className="p-4">Target Class</th>
                      <th className="p-4">Parent Details</th>
                      <th className="p-4">Timing Preference</th>
                      <th className="p-4">Status</th>
                      <th className="p-4 pr-6 text-right">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {enrollments.map((enr) => {
                      const classBatches = batches.filter((b) => b.class_number === enr.student_class);

                      return (
                        <tr key={enr._id} className="hover:bg-slate-50/70 transition-colors">
                          <td className="p-4 pl-6">
                            <div className="font-bold text-[#304b62]">{enr.student_name}</div>
                            <div className="text-xs text-slate-400">{enr.school_name || "CBSE School"}</div>
                          </td>

                          <td className="p-4 font-bold text-[#304b62]">Class {enr.student_class}</td>

                          <td className="p-4">
                            <div className="font-medium text-slate-800">{enr.parent_name}</div>
                            <div className="text-xs text-slate-500">{enr.parent_phone}</div>
                          </td>

                          <td className="p-4">
                            <span className="text-xs bg-slate-100 text-slate-700 px-2.5 py-1 rounded-md font-semibold">
                              {enr.preferred_batch_timing}
                            </span>
                          </td>

                          <td className="p-4">
                            <span
                              className={`text-xs font-bold px-2.5 py-1 rounded-full uppercase tracking-wider ${
                                enr.status === "APPROVED"
                                  ? "bg-emerald-100 text-emerald-700"
                                  : enr.status === "REJECTED"
                                  ? "bg-red-100 text-red-700"
                                  : "bg-amber-100 text-amber-800"
                              }`}
                            >
                              {enr.status}
                            </span>
                          </td>

                          <td className="p-4 pr-6 text-right">
                            {enr.status === "PENDING" ? (
                              <div className="flex items-center justify-end gap-2">
                                <select
                                  className="text-xs border border-slate-200 rounded-lg p-1.5 bg-white text-slate-700 font-medium"
                                  value={selectedBatchForApproval[enr._id] || (classBatches[0]?._id || "")}
                                  onChange={(e) =>
                                    setSelectedBatchForApproval((prev) => ({
                                      ...prev,
                                      [enr._id]: e.target.value,
                                    }))
                                  }
                                >
                                  {classBatches.map((b) => (
                                    <option key={b._id} value={b._id}>
                                      {b.name}
                                    </option>
                                  ))}
                                </select>

                                <button
                                  onClick={() => handleApprove(enr._id, enr.student_class)}
                                  className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3 py-1.5 rounded-lg shadow-sm transition-colors"
                                >
                                  Approve & Enroll
                                </button>
                                <button
                                  onClick={() => handleReject(enr._id)}
                                  className="text-red-500 hover:bg-red-50 p-1.5 rounded-lg"
                                >
                                  <XCircle size={18} />
                                </button>
                              </div>
                            ) : (
                              <span className="text-xs text-slate-400 font-medium">
                                {enr.status === "APPROVED" ? "Enrolled in Batch" : "Declined"}
                              </span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {/* Tab 2: Batches & Timetables */}
        {activeTab === "BATCHES" && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {batches.map((batch) => (
              <div key={batch._id} className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm space-y-4">
                <div className="flex items-center justify-between pb-3 border-b border-slate-100">
                  <span className="text-xs font-bold uppercase tracking-wider text-[#d49539]">
                    Class {batch.class_number}
                  </span>
                  <span className="bg-emerald-100 text-emerald-800 text-xs font-bold px-2 py-0.5 rounded-full">
                    {batch.status}
                  </span>
                </div>

                <h3 className="text-lg font-bold text-[#304b62]">{batch.name}</h3>

                <div className="space-y-1.5 text-xs text-slate-600">
                  <div className="flex items-center gap-2">
                    <Users size={14} className="text-[#304b62]" /> Enrolled Students:{" "}
                    <strong>{batch.student_ids?.length || 0}</strong> / {batch.max_capacity}
                  </div>
                  <div className="flex items-center gap-2">
                    <School size={14} className="text-[#304b62]" /> Teacher:{" "}
                    <strong>{batch.teacher_ids?.[0]?.name || "Rajesh Sharma"}</strong>
                  </div>
                </div>

                {/* Schedule preview */}
                <div className="pt-2 border-t border-slate-100">
                  <div className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Schedule:</div>
                  <div className="flex flex-wrap gap-1.5">
                    {batch.schedule?.map((slot, idx) => (
                      <span key={idx} className="bg-slate-100 text-[#304b62] font-semibold text-xs px-2 py-1 rounded">
                        {slot.day} ({slot.start_time})
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Tab 3: Class Catalog */}
        {activeTab === "CLASSES" && (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
            {classes.map((cls) => (
              <div key={cls._id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm text-center space-y-2">
                <div className="w-12 h-12 rounded-xl bg-[#304b62] text-[#d49539] font-black text-xl flex items-center justify-center mx-auto">
                  {cls.class_number}
                </div>
                <h4 className="font-bold text-[#304b62] text-sm">{cls.name}</h4>
                <div className="text-xs text-slate-500 font-semibold">₹{cls.monthly_base_fee || 2000}/mo</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;
